public static int computeWithHashSet(int[] nums) {
    if (nums.length == 0)
        return 0;

    Set<Integer> set = new HashSet<>();
    for (int num : nums) {
        set.add(num);
    }

    int longest = 0;
    for (int num : set) {
        if (!set.contains(num - 1)) {
            int current = num;
            int length = 0;
            while (set.contains(current)) {
                length++;
                current++;
            }
            longest = Math.max(longest, length);
        }
    }
    return longest;
}

